   380  MRB_API mrb_value
   381  mrb_f_raise(mrb_state *mrb, mrb_value self)
   382  {
   383    mrb_value exc, mesg;
   384    mrb_int argc;
   385
   386    argc = mrb_get_args(mrb, "|oo", &exc, &mesg);
   387    mrb->c->ci->mid = 0;
   388    switch (argc) {
   389    case 0:
   390      mrb_raise(mrb, E_RUNTIME_ERROR, "");
   391      break;
   392    case 1:
