   394        mesg = exc;
   395        exc = mrb_obj_value(E_RUNTIME_ERROR);
   396      }
   397      else {
   398        mesg = mrb_nil_value();
   399      }
   400      /* fall through */
   401    default:
   402      exc = mrb_make_exception(mrb, exc, mesg);
   403      mrb_exc_raise(mrb, exc);
   404      break;
   405    }
   406    return mrb_nil_value();            /* not reached */
   407  }
