   461  mrb_value
   462  mrb_make_exception(mrb_state *mrb, mrb_value exc, mrb_value mesg)
   463  {
   464    mrb_int n = 1;
   465
   466    if (mrb_nil_p(mesg)) {
   467      n = 0;
   468    }
   469    if (mrb_class_p(exc)) {
   470      exc = mrb_funcall_argv(mrb, exc, MRB_SYM(new), n, &mesg);
   471    }
   472    else if (mrb_exception_p(exc)) {
   473      if (n > 0) {
   474        exc = mrb_obj_clone(mrb, exc);
   475        mrb_exc_mesg_set(mrb, mrb_exc_ptr(exc), mesg);
   476      }
   477    }
   478    else {
   479      mrb_raise(mrb, E_TYPE_ERROR, "exception class/object expected");
   480    }
   481    if (mrb_type(exc) != MRB_TT_EXCEPTION) {
   482      mrb_raise(mrb, E_EXCEPTION, "exception object expected");
   483    }
   484    return exc;
   485  }
