   487  MRB_API mrb_noreturn void
   488  mrb_sys_fail(mrb_state *mrb, const char *mesg)
   489  {
   490    struct RClass *sce;
   491    mrb_int no;
   492
   493    no = (mrb_int)errno;
   494    if (mrb_class_defined_id(mrb, MRB_SYM(SystemCallError))) {
   495      sce = mrb_class_get_id(mrb, MRB_SYM(SystemCallError));
   496      if (mesg != NULL) {
   497        mrb_funcall_id(mrb, mrb_obj_value(sce), MRB_SYM(_sys_fail), 2, mrb_fixnum_value(no), mrb_str_new_cstr(mrb, mesg));
   498      }
   499      else {
   500        mrb_funcall_id(mrb, mrb_obj_value(sce), MRB_SYM(_sys_fail), 1, mrb_fixnum_value(no));
   501      }
   502    }
   503
   504    mrb_raise(mrb, E_RUNTIME_ERROR, mesg);
   505  }
